function modal(title,body,saveLabel,fn){const key="pooshe-draft:"+title;$("#modal").innerHTML='<div class="shade"><section class="modal"><div class="row"><h2>'+title+'</h2><small class="autosave-state" id="draftState">ذخیره خودکار فعال است</small><button id="x">×</button></div>'+body+'<div class="actions"><button class="outline" id="cancel">بستن</button><button class="primary" id="save">'+saveLabel+'</button></div></section></div>';const form=$("#modal .modal");form.querySelectorAll(".jalali-date").forEach(el=>{el.addEventListener("focus",()=>openJalaliPicker(el));el.addEventListener("click",()=>openJalaliPicker(el))});try{const d=JSON.parse(localStorage.getItem(key)||"{}");Object.entries(d).forEach(([id,v])=>{const el=form.querySelector("#"+CSS.escape(id));if(el&&el.type!=="file")el.value=v})}catch{}let timer;const draft=()=>{const d={};form.querySelectorAll("input,textarea,select").forEach(el=>{if(el.id&&el.type!=="file")d[el.id]=el.value});try{localStorage.setItem(key,JSON.stringify(d));$("#draftState").textContent="پیش‌نویس ذخیره شد"}catch{$("#draftState").textContent="ذخیره پیش‌نویس ممکن نیست"}};form.addEventListener("input",()=>{clearTimeout(timer);$("#draftState").textContent="در حال ذخیره...";timer=setTimeout(draft,250)});form.addEventListener("change",draft);form.addEventListener("focusout",draft);$("#x").onclick=$("#cancel").onclick=()=>$("#modal").innerHTML="";$("#save").onclick=async()=>{const result=await fn();if(result!==false)localStorage.removeItem(key)}}
function jalaliParts(iso){const d=new Date(iso+"T12:00:00");const p=new Intl.DateTimeFormat("en-u-ca-persian-nu-latn",{year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(d);return Object.fromEntries(p.filter(x=>x.type!=="literal").map(x=>[x.type,+x.value]))}
